const path = '/data/MITRE_ATT&CK';

const raw = items[0].json.data;
const input = typeof raw === 'string' ? JSON.parse(raw) : raw;
const assert = (cond, msg) => { if (!cond) throw new Error(msg); };

assert('spec_version' in input, "Failure reading version info in JSON file");
assert('objects' in input, "Failure reading objects in JSON file");
assert(input.spec_version === '2.0', "Unsupported STIX version");

const o = {};
for (const i of input.objects) {
    assert('type' in i, `type information is missing in entry ${JSON.stringify(i)}`);
    assert('id' in i, `id field is missing in entry ${JSON.stringify(i)}`);

    if (i.revoked === true || i.x_mitre_deprecated === true) continue;

    const id = i.id;
    const t = i.type;

    if (!o[t]) o[t] = {};
    o[t][id] = i;
}

// Build tactics dictionary
const tactics = {};
for (const [_, tactic] of Object.entries(o['x-mitre-tactic'] || {})) {
    const shortName = tactic.x_mitre_shortname || '';
    const name = tactic.name || '';
    const extRef = tactic.external_references?.[0] || {};
    const id = extRef.external_id || '';
    const url = extRef.url || '';
    tactics[shortName] = name;
}

// Mini Markdown parser
function minimd(s, fmt = 'text') {
    if (!s) return '';
    if (fmt === 'html') {
        s = s.replace(/<code>(.*?)<\/code>/g, (_, code) => `<code>${code.replace('<', '&lt;')}</code>`);
        s = s.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
        s = s.replace(/\[([^\[]*)\]\((.*?)\)/g, '<a href="$2">$1</a>');
        s = s.replace(/(?:^|\n)#+([^\n]*)/g, '<b><u>$1</u></b><br/>');
        s = s.replace(/"https:\/\/attack\.mitre\.org\/techniques\/(.*?)"/g, (_, tech) => `"${tech.replace(/\//g, ".")}"`);
        s = s.replace(/\n/g, '<br/>');
    } else {
        s = s.replace(/(?:^|\n)#+([^\n]*)/g, '# $1 #\n');
        s = s.replace(/<code>(.*?)<\/code>/g, (_, code) => '`' + code + '`');
        s = s.replace(/https:\/\/attack\.mitre\.org\/(techniques|tactics|software)\/([^\]\)"\)]+)/g, (_, __, tech) => tech.replace(/\//g, "."));
        s = s.replace(/<br>/g, '\n');
    }
    return s;
}

// Extract techniques
const tech = {};
for (const [tn, t] of Object.entries(o['attack-pattern'] || {})) {
    let mitreId = '';
    let mitreUrl = '';

    for (const r of (t.external_references || [])) {
        if (r.source_name === 'mitre-attack') {
            mitreId = r.external_id || '';
            mitreUrl = r.url || '';
            break;
        }
    }

    assert(mitreId !== '', `Didn't find a mitre id for ${JSON.stringify(t)}`);

    const name = t.name || '';
    const platforms = t.x_mitre_platforms || [];
    const phases = (t.kill_chain_phases || []).filter(p => p.kill_chain_name === 'mitre-attack')
        .map(p => tactics[p.phase_name] || p.phase_name);
    const dataSources = t.x_mitre_data_sources || [];
    const description = minimd(t.description || '');
    const detection = minimd(t.x_mitre_detection || '');

    tech[mitreId] = { name, id: tn, url: mitreUrl, platforms, phases, dataSources, detection, description };
}

// Create CSV
function toCsv(rows, headers) {
    const escape = (str) => `"${String(str).replace(/"/g, '""')}"`;
    const csv = [headers.map(escape).join(',')];
    for (const row of rows) {
        csv.push(headers.map(h => escape(row[h] || '')).join(','));
    }
    return csv.join('\n');
}

const headers = ['name', 'id', 'url', 'platforms', 'kill chain phases', 'description', 'data sources', 'detection'];
const rows = [];

for (const tid of Object.keys(tech).sort()) {
    const t = tech[tid];
    rows.push({
        name: t.name,
        id: tid,
        url: t.url,
        platforms: t.platforms.join(', '),
        'kill chain phases': t.phases.join(', '),
        description: t.description,
        'data sources': t.dataSources.join(', '),
        detection: t.detection
    });
}

const csvContent = toCsv(rows, headers);

// Save file path
const filePath = `${path}/enterprise-attack.csv`;

// Return JSON + Binary
return [
  {
    json: {
      message: `Processed ${Object.keys(tech).length} techniques`,
      rowCount: Object.keys(tech).length,
      filePath
    },
    binary: {
      data: {
        data: Buffer.from(csvContent, 'utf-8').toString('base64'),
        mimeType: 'text/csv',
        fileName: 'enterprise-attack.csv'
      }
    }
  }
];

// Update local git ref to match remote
const remoteCommit = $node['Get Latest MITRE Commit'].json.sha;

return {
  json: {
    message: 'MITRE ATT&CK data updated successfully',
    mitre_commit: remoteCommit,
    timestamp: new Date().toISOString()
  }
};

return {
  json: {
    message: 'MITRE ATT&CK data is up to date',
    timestamp: new Date().toISOString()
  }
};

// Log error and provide fallback
const error = $input.first().json.error || 'Unknown error occurred';

return {
  json: {
    error: true,
    message: `Failed to update MITRE ATT&CK data: ${error}`,
    timestamp: new Date().toISOString()
  }
};
